[metadata] {"type": "create", "filePath": "/app/poster.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Large Language Models in Medicine - Academic Poster</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&family=Source+Serif+4:ital,wght@0,300;0,400;0,600;0,700;1,400&display=swap');

  * { margin: 0; padding: 0; box-sizing: border-box; }

  :root {
    --navy: #0f1b2d;
    --navy-mid: #162338;
    --navy-light: #1c2d47;
    --teal: #3b8ea5;
    --teal-light: #5ba8bf;
    --steel: #6b8aaa;
    --steel-light: #8faec8;
    --ice: #e8f0f7;
    --white: #ffffff;
    --amber: #e8913a;
    --coral: #d9534f;
    --coral-light: #e87c79;
    --text-primary: #e8f0f7;
    --text-secondary: #8faec8;
    --text-body: #c5d5e4;
    --divider: rgba(91,168,191,0.2);
  }

  body {
    width: 2384px;
    height: 3370px;
    background: var(--navy);
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    color: var(--text-primary);
    overflow: hidden;
  }

  .poster {
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction: column;
    padding: 60px 70px;
  }

  /* ── HEADER ── */
  .header {
    text-align: center;
    padding-bottom: 40px;
    border-bottom: 3px solid var(--teal);
    margin-bottom: 10px;
  }
  .header .venue {
    font-size: 22px;
    font-weight: 500;
    color: var(--teal-light);
    letter-spacing: 4px;
    text-transform: uppercase;
    margin-bottom: 20px;
  }
  .header h1 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 72px;
    font-weight: 700;
    line-height: 1.15;
    color: var(--white);
    margin-bottom: 22px;
    letter-spacing: -0.5px;
  }
  .header .subtitle {
    font-size: 27px;
    font-weight: 300;
    color: var(--steel-light);
    line-height: 1.5;
    max-width: 1700px;
    margin: 0 auto;
  }

  /* ── METRICS BANNER ── */
  .metrics-banner {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 28px;
    padding: 40px 0;
    margin-bottom: 10px;
  }
  .metric-card {
    background: var(--navy-mid);
    border: 1px solid var(--divider);
    border-radius: 16px;
    padding: 32px 28px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .metric-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: var(--teal);
  }
  .metric-card.risk::before {
    background: var(--amber);
  }
  .metric-card .value {
    font-size: 64px;
    font-weight: 800;
    color: var(--teal-light);
    line-height: 1.1;
    margin-bottom: 10px;
  }
  .metric-card.risk .value {
    color: var(--amber);
  }
  .metric-card .label {
    font-size: 20px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 8px;
  }
  .metric-card .context {
    font-size: 15px;
    color: var(--text-secondary);
    line-height: 1.45;
  }

  /* ── SECTION DIVIDER ── */
  .section-divider {
    width: 100%;
    height: 1px;
    background: var(--divider);
    margin: 10px 0;
  }

  /* ── MAIN CONTENT GRID ── */
  .content-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 50px;
    flex: 1;
  }
  .col-left, .col-right {
    display: flex;
    flex-direction: column;
    gap: 36px;
  }

  /* ── SECTION STYLING ── */
  .section {
    background: var(--navy-mid);
    border: 1px solid var(--divider);
    border-radius: 16px;
    padding: 36px 38px;
    position: relative;
  }
  .section.risk-section {
    border-color: rgba(232,145,58,0.3);
  }
  .section h2 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 32px;
    font-weight: 700;
    color: var(--white);
    margin-bottom: 6px;
    display: flex;
    align-items: center;
    gap: 14px;
  }
  .section h2 .num {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 10px;
    background: var(--teal);
    color: var(--white);
    font-family: 'Inter', sans-serif;
    font-size: 20px;
    font-weight: 700;
    flex-shrink: 0;
  }
  .section h2 .num.risk-num {
    background: var(--amber);
  }
  .section .section-desc {
    font-size: 18px;
    color: var(--text-secondary);
    margin-bottom: 24px;
    line-height: 1.5;
    padding-left: 54px;
  }

  /* ── TABLE ── */
  .app-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
    font-size: 17px;
    margin-top: 12px;
  }
  .app-table thead th {
    background: var(--navy-light);
    color: var(--teal-light);
    font-weight: 600;
    padding: 14px 18px;
    text-align: left;
    font-size: 16px;
    text-transform: uppercase;
    letter-spacing: 1px;
  }
  .app-table thead th:first-child { border-radius: 10px 0 0 0; }
  .app-table thead th:last-child { border-radius: 0 10px 0 0; }
  .app-table tbody td {
    padding: 14px 18px;
    border-bottom: 1px solid var(--divider);
    color: var(--text-body);
    line-height: 1.4;
  }
  .app-table tbody tr:last-child td { border-bottom: none; }
  .maturity-badge {
    display: inline-block;
    padding: 3px 12px;
    border-radius: 20px;
    font-size: 14px;
    font-weight: 500;
  }
  .maturity-badge.pilot { background: rgba(59,142,165,0.2); color: var(--teal-light); }
  .maturity-badge.research { background: rgba(107,138,170,0.15); color: var(--steel-light); }
  .maturity-badge.early { background: rgba(91,168,191,0.2); color: #7ec8db; }
  .maturity-badge.active { background: rgba(59,142,165,0.35); color: #9cdced; }
  .maturity-badge.emerging { background: rgba(107,138,170,0.1); color: var(--steel); }

  /* ── BENCHMARK BARS ── */
  .benchmark-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 20px;
    margin-top: 12px;
  }
  .benchmark-item {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .benchmark-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
  }
  .benchmark-name {
    font-size: 20px;
    font-weight: 600;
    color: var(--text-primary);
  }
  .benchmark-score {
    font-size: 26px;
    font-weight: 800;
    color: var(--teal-light);
  }
  .benchmark-bar-bg {
    width: 100%;
    height: 28px;
    background: var(--navy);
    border-radius: 14px;
    overflow: hidden;
    position: relative;
  }
  .benchmark-bar-fill {
    height: 100%;
    border-radius: 14px;
    transition: width 0.3s;
  }
  .benchmark-bar-bg .passing-line {
    position: absolute;
    left: 60%;
    top: 0;
    bottom: 0;
    width: 2px;
    background: var(--amber);
  }
  .benchmark-bar-bg .passing-label {
    position: absolute;
    left: 60%;
    top: -22px;
    transform: translateX(-50%);
    font-size: 13px;
    color: var(--amber);
    font-weight: 500;
  }
  .benchmark-detail {
    font-size: 15px;
    color: var(--text-secondary);
    line-height: 1.4;
  }

  /* ── RISK ITEMS ── */
  .risk-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 18px;
    margin-top: 8px;
  }
  .risk-item {
    display: flex;
    gap: 16px;
    align-items: flex-start;
  }
  .risk-icon {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    font-size: 20px;
    font-weight: 700;
  }
  .risk-icon.high {
    background: rgba(217,83,79,0.2);
    color: var(--coral);
    border: 1px solid rgba(217,83,79,0.3);
  }
  .risk-icon.medium {
    background: rgba(232,145,58,0.15);
    color: var(--amber);
    border: 1px solid rgba(232,145,58,0.25);
  }
  .risk-body h3 {
    font-size: 20px;
    font-weight: 600;
    color: var(--text-primary);
    margin-bottom: 4px;
  }
  .risk-body p {
    font-size: 16px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .risk-body .risk-stat {
    color: var(--amber);
    font-weight: 600;
  }

  /* ── FRAMEWORK ── */
  .framework-section {
    background: linear-gradient(135deg, var(--navy-mid) 0%, rgba(59,142,165,0.08) 100%);
    border: 2px solid rgba(59,142,165,0.3);
    border-radius: 20px;
    padding: 40px 44px;
    margin-top: 10px;
  }
  .framework-section h2 {
    font-family: 'Source Serif 4', Georgia, serif;
    font-size: 34px;
    font-weight: 700;
    color: var(--white);
    margin-bottom: 8px;
    text-align: center;
  }
  .framework-desc {
    font-size: 19px;
    color: var(--text-secondary);
    text-align: center;
    margin-bottom: 30px;
    line-height: 1.5;
  }
  .framework-grid {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 20px;
  }
  .fw-card {
    background: var(--navy);
    border: 1px solid var(--divider);
    border-radius: 14px;
    padding: 24px 20px;
    text-align: center;
    position: relative;
  }
  .fw-card .fw-num {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: var(--teal);
    color: var(--white);
    font-size: 18px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 14px;
  }
  .fw-card h3 {
    font-size: 18px;
    font-weight: 700;
    color: var(--white);
    margin-bottom: 10px;
    line-height: 1.3;
  }
  .fw-card p {
    font-size: 14.5px;
    color: var(--text-secondary);
    line-height: 1.5;
  }
  .fw-arrow {
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--teal);
    font-size: 28px;
    padding-top: 20px;
  }

  /* ── FOOTER ── */
  .footer {
    text-align: center;
    padding-top: 28px;
    margin-top: 10px;
    border-top: 1px solid var(--divider);
  }
  .footer p {
    font-size: 16px;
    color: var(--text-secondary);
    line-height: 1.6;
  }
  .footer .source {
    font-style: italic;
    color: var(--steel);
  }

  /* ── INFOGRAPHIC CONTAINERS ── */
  .infographic-container {
    width: 100%;
    min-height: 300px;
    margin-top: 12px;
    border-radius: 12px;
    overflow: hidden;
  }

  /* ── OVERVIEW SECTION ── */
  .overview-content {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-top: 12px;
  }
  .overview-text {
    font-size: 17.5px;
    color: var(--text-body);
    line-height: 1.65;
  }
  .overview-text strong {
    color: var(--teal-light);
    font-weight: 600;
  }
  .overview-stats {
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  .ov-stat {
    background: var(--navy);
    border-radius: 12px;
    padding: 18px 22px;
    display: flex;
    align-items: center;
    gap: 18px;
  }
  .ov-stat .ov-val {
    font-size: 34px;
    font-weight: 800;
    color: var(--teal-light);
    white-space: nowrap;
  }
  .ov-stat .ov-label {
    font-size: 15px;
    color: var(--text-secondary);
    line-height: 1.4;
  }
</style>
</head>
<body>

<div class="poster">

  <!-- HEADER -->
  <div class="header">
    <div class="venue">Medical AI &amp; Digital Health Conference 2024</div>
    <h1>Large Language Models in Medicine:<br>Opportunities, Risks, and the Path Forward</h1>
    <div class="subtitle">A comprehensive review of how large language models are transforming clinical practice, medical research, and healthcare delivery — along with the critical challenges that must be addressed.</div>
  </div>

  <!-- HEADLINE METRICS -->
  <div class="metrics-banner">
    <div class="metric-card">
      <div class="value">&gt;90%</div>
      <div class="label">GPT-4 USMLE Score</div>
      <div class="context">Exceeded the passing threshold on all three steps of the United States Medical Licensing Examination</div>
    </div>
    <div class="metric-card">
      <div class="value">500+</div>
      <div class="label">PubMed Articles (2023)</div>
      <div class="context">Peer-reviewed publications on LLMs in medicine published in a single year</div>
    </div>
    <div class="metric-card risk">
      <div class="value">Up to 30%</div>
      <div class="label">Hallucination Rate</div>
      <div class="context">LLMs can generate fabricated medical references or inaccurate clinical information</div>
    </div>
    <div class="metric-card">
      <div class="value">$10.5B</div>
      <div class="label">Projected Market (2030)</div>
      <div class="context">Global healthcare LLM market projection by 2030</div>
    </div>
  </div>

  <div class="section-divider"></div>

  <!-- MAIN TWO-COLUMN CONTENT -->
  <div class="content-grid">

    <!-- LEFT COLUMN -->
    <div class="col-left">

      <!-- Section 1: Overview -->
      <div class="section">
        <h2><span class="num">1</span> What Are LLMs and Why Do They Matter?</h2>
        <div class="section-desc">Foundation models trained on vast text corpora, now reshaping clinical practice</div>
        <div class="overview-content">
          <div class="overview-text">
            Large language models such as <strong>GPT-4</strong>, <strong>Med-PaLM 2</strong>, and <strong>LLaMA</strong> have rapidly entered the healthcare landscape, demonstrating remarkable capabilities in understanding and generating medical text.
            <br><br>
            Published in <em>Nature Medicine</em> (July 2023), a landmark review examined how these foundation models are poised to reshape clinical practice, biomedical research, and medical education. The pace of adoption has been extraordinary.
          </div>
          <div class="overview-stats">
            <div class="ov-stat">
              <div class="ov-val">500+</div>
              <div class="ov-label">Peer-reviewed publications on LLMs in medicine in 2023 alone</div>
            </div>
            <div class="ov-stat">
              <div class="ov-val">$10.5B</div>
              <div class="ov-label">Projected global healthcare LLM market by 2030</div>
            </div>
            <div class="ov-stat">
              <div class="ov-val">3</div>
              <div class="ov-label">Major model families: GPT-4, Med-PaLM 2, LLaMA</div>
            </div>
          </div>
        </div>
      </div>

      <!-- Section 2: Applications Table -->
      <div class="section">
        <h2><span class="num">2</span> Key Clinical &amp; Research Applications</h2>
        <div class="section-desc">Spanning documentation, diagnostics, communication, education, and research</div>
        <table class="app-table">
          <thead>
            <tr>
              <th>Application Area</th>
              <th>Example Use Cases</th>
              <th>Maturity</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td><strong>Clinical Documentation</strong></td>
              <td>Automated note generation, discharge summaries</td>
              <td><span class="maturity-badge pilot">Pilot Deployments</span></td>
            </tr>
            <tr>
              <td><strong>Diagnostic Support</strong></td>
              <td>Differential diagnosis, radiology report interpretation</td>
              <td><span class="maturity-badge research">Research Stage</span></td>
            </tr>
            <tr>
              <td><strong>Patient Communication</strong></td>
              <td>Answering patient questions, simplifying medical jargon</td>
              <td><span class="maturity-badge early">Early Adoption</span></td>
            </tr>
            <tr>
              <td><strong>Medical Education</strong></td>
              <td>Exam preparation, case-based learning, AI tutoring</td>
              <td><span class="maturity-badge active">Active Use</span></td>
            </tr>
            <tr>
              <td><strong>Biomedical Research</strong></td>
              <td>Literature synthesis, hypothesis generation, protocol drafting</td>
              <td><span class="maturity-badge emerging">Emerging</span></td>
            </tr>
          </tbody>
        </table>
      </div>

      <!-- Section 3: Performance Benchmarks -->
      <div class="section">
        <h2><span class="num">3</span> Performance Benchmarks &amp; Evidence</h2>
        <div class="section-desc">Quantitative evidence on LLM performance in standardized medical examinations</div>
        <ul class="benchmark-list">
          <li class="benchmark-item">
            <div class="benchmark-header">
              <span class="benchmark-name">GPT-4 — USMLE (All Steps)</span>
              <span class="benchmark-score">>90%</span>
            </div>
            <div class="benchmark-bar-bg">
              <span class="passing-label">~60% Pass</span>
              <span class="passing-line"></span>
              <div class="benchmark-bar-fill" style="width:92%; background: linear-gradient(90deg, #3b8ea5, #5ba8bf);"></div>
            </div>
            <div class="benchmark-detail">Substantially exceeded the ~60% passing threshold on all three USMLE steps</div>
          </li>
          <li class="benchmark-item">
            <div class="benchmark-header">
              <span class="benchmark-name">Med-PaLM 2 — MedQA</span>
              <span class="benchmark-score">86.5%</span>
